import sys,json,urllib.request,urllib.parse
sys.path.insert(0,"engine")
from odata_client import ODataClient
c=ODataClient()
ENT=urllib.parse.quote("AccountingRegister_Хозрасчетный_RecordType")
def raw(path):
    req=urllib.request.Request(c.url+path); req.add_header("Authorization",c._auth); req.add_header("Accept","application/json")
    with urllib.request.urlopen(req,timeout=120,context=c._ctx) as r: return json.loads(r.read().decode())
for exp in ("ExtDimensionsDr","ExtDimensionsDr,ExtDimensionsCr","ExtDimensionDr","СубконтоDr"):
    p="/%s?$format=json&$top=1&$expand=%s"%(ENT,urllib.parse.quote(exp))
    try:
        js=raw(p); rec=(js.get("value") or [{}])[0]
        arr={k:v for k,v in rec.items() if isinstance(v,(list,dict))}
        print("expand=%-32s OK | масиви: %s"%(exp, list(arr.keys()) or "немає"))
        for k,v in arr.items(): print("      ",k,"=",json.dumps(v,ensure_ascii=False)[:320])
        if arr: break
    except Exception as e:
        print("expand=%-32s помилка: %s"%(exp,str(e)[:90]))
EOF
